var _markdown = "\n\n`sa` · 扩展 `SAMPFUNCS` · 仅 SA-MP；需 SAMPFUNCS\n\n共 5 条。调用见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 读写 / 存在 [#读写--存在]\n\n<Opcode id=\"0BFC\" name=\"SF_SET_CUSTOM_GLOBAL_VARIABLE\" member=\"SfGVar.Set\">\n  设置指定名称自定义全局变量的值。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0BFC SF_SET_CUSTOM_GLOBAL_VARIABLE\n      in: name, value\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if sfSetCustomGlobalVariable(name, value) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (SfGVar.Set(name, value)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0BFD\" name=\"SF_GET_CUSTOM_GLOBAL_VARIABLE\" member=\"SfGVar.Get\">\n  返回指定名称自定义全局变量的值。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0BFD SF_GET_CUSTOM_GLOBAL_VARIABLE\n      in: name\n      out: value\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local value = sfGetCustomGlobalVariable(name)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const value = SfGVar.Get(name)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0C5F\" name=\"SF_DOES_CUSTOM_GLOBAL_VARIABLE_EXIST\" member=\"SfGVar.DoesExist\">\n  若指定名称的自定义全局变量存在则为真。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C5F SF_DOES_CUSTOM_GLOBAL_VARIABLE_EXIST\n      in: name\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if sfDoesCustomGlobalVariableExist(name) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (SfGVar.DoesExist(name)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 权限 [#权限]\n\n<Opcode id=\"0C60\" name=\"SF_SET_CUSTOM_GLOBAL_VARIABLE_SCOPE\" member=\"SfGVar.SetScope\">\n  设置指定脚本对自定义全局变量的读写权限。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C60 SF_SET_CUSTOM_GLOBAL_VARIABLE_SCOPE\n      in: gVarName, scriptPtr, canRead, canWrite\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if sfSetCustomGlobalVariableScope(gVarName, scriptPtr, canRead, canWrite) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (SfGVar.SetScope(gVarName, scriptPtr, canRead, canWrite)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0C61\" name=\"SF_GET_CUSTOM_GLOBAL_VARIABLE_SCOPE\" member=\"SfGVar.GetScope\">\n  返回指定脚本对自定义全局变量的读写权限。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C61 SF_GET_CUSTOM_GLOBAL_VARIABLE_SCOPE\n      in: gVarName, scriptPtr\n      out: canRead, canWrite\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local canRead, canWrite = sfGetCustomGlobalVariableScope(gVarName, scriptPtr)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const { canRead, canWrite } = SfGVar.GetScope(gVarName, scriptPtr)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
